class Solution {
    struct Tx {
        string name;
        int time;
        int amount;
        string city;
        int index;
    };
public:
    vector<string> invalidTransactions(vector<string>& transactions) {
        int n = transactions.size();
        vector<Tx> txs(n);
        for (int i = 0; i < n; ++i) {
            const string& t = transactions[i];
            int p1 = t.find(',');
            int p2 = t.find(',', p1 + 1);
            int p3 = t.find(',', p2 + 1);
            txs[i].name = t.substr(0, p1);
            txs[i].time = stoi(t.substr(p1 + 1, p2 - p1 - 1));
            txs[i].amount = stoi(t.substr(p2 + 1, p3 - p2 - 1));
            txs[i].city = t.substr(p3 + 1);
            txs[i].index = i;
        }

        sort(txs.begin(), txs.end(), [](const Tx& a, const Tx& b) {
            if (a.name != b.name) return a.name < b.name;
            return a.time < b.time;
        });

        vector<bool> is_invalid(n, false);

        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && txs[j].name == txs[i].name) {
                j++;
            }
            int group_size = j - i;
            vector<int> diff(group_size + 1, 0);
            unordered_map<string, int> city_counts;
            int distinct_cities = 0;
            int L = 0;
            for (int R = 0; R < group_size; ++R) {
                city_counts[txs[i + R].city]++;
                if (city_counts[txs[i + R].city] == 1) {
                    distinct_cities++;
                }
                while (txs[i + R].time - txs[i + L].time > 60) {
                    city_counts[txs[i + L].city]--;
                    if (city_counts[txs[i + L].city] == 0) {
                        distinct_cities--;
                    }
                    L++;
                }
                if (distinct_cities > 1) {
                    diff[L]++;
                    diff[R + 1]--;
                }
            }

            int curr = 0;
            for (int k = 0; k < group_size; ++k) {
                curr += diff[k];
                if (curr > 0 || txs[i + k].amount > 1000) {
                    is_invalid[txs[i + k].index] = true;
                }
            }
            i = j;
        }

        vector<string> res;
        for (int k = 0; k < n; ++k) {
            if (is_invalid[k]) {
                res.push_back(transactions[k]);
            }
        }
        return res;
    }
};
